package com.elogistic.backend.workflow.internal.web;

import com.elogistic.backend.identity.api.customer.CustomerAdmission;
import com.elogistic.backend.merchant.api.customer.PilotCoverage;
import com.elogistic.backend.orders.api.*;
import com.elogistic.backend.pricing.api.*;
import com.elogistic.backend.finance.api.BusinessObligations;
import jakarta.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.net.URI;
import java.time.Clock;
import java.util.*;
import java.util.function.Function;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.context.annotation.Profile;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import tools.jackson.core.StreamReadFeature;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;
import static com.elogistic.backend.workflow.internal.web.BusinessPreparationHttp.*;
import static com.elogistic.backend.workflow.internal.web.CustomerProfileHttp.problem;

/** Organization admission + quote + Orders + Finance share one physical transaction. */
@RestController @Profile("customer")
public final class BusinessShippingHttp {
    @ModelAttribute public void privateResponse(jakarta.servlet.http.HttpServletResponse response){response.setHeader("Cache-Control","no-store");}
    private static final String BASE="/api/v1/merchant-organizations/{organizationId}";
    private static final JsonMapper JSON=JsonMapper.builder().enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION).build();
    private final BusinessPreparationHttp admission;private final BusinessPreparations drafts;private final BusinessQuotes quotes;private final BusinessShipments shipments;private final BusinessObligations finance;private final PilotCoverage coverage;private final Clock clock;
    public BusinessShippingHttp(BusinessPreparationHttp admission,BusinessPreparations drafts,BusinessQuotes quotes,BusinessShipments shipments,BusinessObligations finance,PilotCoverage coverage,@Qualifier("identityHttpClock")Clock clock){this.admission=admission;this.drafts=drafts;this.quotes=quotes;this.shipments=shipments;this.finance=finance;this.coverage=coverage;this.clock=clock;}
    private record Scope(BusinessPreparations.Access preparation,CustomerAdmission.Context identity) implements BusinessQuotes.Access,BusinessObligations.Access {
        public UUID actorAccountId(){return preparation.actorAccountId();}public UUID requestId(){return preparation.requestId();}public UUID organizationId(){return preparation.scope().context().organizationId();}
        public void requireCurrent(){preparation.requireCurrent();}public void meaningfulAction(){preparation.meaningfulAction();}
        public void requirePermission(String p,UUID site){requireCurrent();if(!preparation.scope().permits(p,site))throw new BusinessPreparations.Failure("RESOURCE_NOT_FOUND");}
    }
    private <T>T execute(String org,Function<Scope,T> work){try{return admission.executeWithContext(org,(a,c)->work.apply(new Scope(a,c)));}catch(PilotQuoteFailure failure){throw problem(switch(failure.code()){case VALIDATION_FAILED->400;case RESOURCE_NOT_FOUND->404;case PILOT_DISABLED->503;case UNSUPPORTED_ROUTE,PARCEL_NOT_ELIGIBLE,ORDINARY_GOODS_REQUIRED->422;default->409;},failure.code().name());}}
    private static void query(HttpServletRequest r,Set<String> fields){if(!fields.containsAll(r.getParameterMap().keySet())||r.getParameterMap().values().stream().anyMatch(v->v.length!=1))throw problem(400,"VALIDATION_FAILED");}
    private PilotQuotes.Route route(Scope a,String origin,String destination){var r=coverage.catalog(a.identity()).routes().stream().filter(v->v.originCode().equals(origin)&&v.destinationCode().equals(destination)).findFirst().orElseThrow(()->new PilotQuoteFailure(PilotQuoteFailure.Code.UNSUPPORTED_ROUTE));return new PilotQuotes.Route(r.datasetVersion(),r.originCode(),r.destinationCode(),r.classification(),r.dropOffCode());}
    @GetMapping(BASE+"/shipping-catalog") public Map<String,Object> catalog(@PathVariable String organizationId,HttpServletRequest r){query(r,Set.of());return execute(organizationId,a->{var c=quotes.contract(a);PilotQuotes.Rules tariff=null;try{tariff=quotes.rules(a);}catch(PilotQuoteFailure unavailable){if(unavailable.code()!=PilotQuoteFailure.Code.PILOT_DISABLED)throw unavailable;}boolean priced=tariff!=null;var s=a.preparation().scope();Map<String,Object> result=new LinkedHashMap<>();result.put("simulation",true);result.put("serviceCode","ROAD_STANDARD");result.put("quoteEnabled",priced&&(s.permits("shipment.quote",null)||!s.facilities("shipment.quote").isEmpty()));result.put("bookingEnabled",priced&&(s.permits("shipment.book",null)||!s.facilities("shipment.book").isEmpty()));result.put("coverage",coverage.catalog(a.identity()));result.put("tariff",tariff);result.put("contract",c.orElse(null));result.put("paymentMethod","CASH_ON_HANDOVER");result.put("payer","SENDER");result.put("paymentCollectionEnabled",false);return result;});}
    private Map<String,Object> quoteView(Scope a,BusinessQuotes.Quote q){boolean usable=quotes.usable(a,q);if(usable){var d=drafts.get(a.preparation(),q.preparationId());usable=d.state().equals("DRAFT")&&d.version()==q.preparationVersion()&&Objects.equals(d.facilityId(),q.facilityId())&&route(a,q.route().originCode(),q.route().destinationCode()).equals(q.route())&&quotes.rules(a).version().equals(q.tariffVersion());}return Map.of("quote",q,"usable",usable,"serverTime",clock.instant());}
    @PostMapping(BASE+"/shipment-preparations/{id}/quotes") public ResponseEntity<Map<String,Object>> quote(@PathVariable String organizationId,@PathVariable String id,HttpServletRequest r)throws IOException{query(r,Set.of());UUID key=key(r),target=uuid(id);long expected=version(r);var v=body(r,Set.of("originCode","destinationCode","ordinaryGoodsConfirmed"));if(!v.get("originCode").isString()||!v.get("destinationCode").isString()||!v.get("ordinaryGoodsConfirmed").isBoolean())throw problem(400,"VALIDATION_FAILED");var result=execute(organizationId,a->{var d=drafts.get(a.preparation(),target);if(d.version()!=expected||!d.state().equals("DRAFT"))throw new BusinessPreparations.Failure("PRECONDITION_STALE");a.preparation().scope().requireActiveFacility(d.facilityId());var route=route(a,v.get("originCode").asString(),v.get("destinationCode").asString());var facts=d.input().parcels().stream().map(p->new PilotQuotes.Parcel(p.weightGrams(),p.lengthMm(),p.widthMm(),p.heightMm())).toList();return quoteView(a,quotes.create(a,new BusinessQuotes.Request(d.id(),d.version(),d.facilityId(),route,facts,v.get("ordinaryGoodsConfirmed").asBoolean()),key));});var q=(BusinessQuotes.Quote)result.get("quote");return ResponseEntity.created(URI.create("/api/v1/merchant-organizations/"+organizationId+"/shipping-quotes/"+q.id())).cacheControl(CacheControl.noStore()).body(result);}
    @GetMapping(BASE+"/shipping-quotes/{id}") public Map<String,Object> getQuote(@PathVariable String organizationId,@PathVariable String id,HttpServletRequest r){query(r,Set.of());return execute(organizationId,a->quoteView(a,quotes.get(a,uuid(id))));}
    @GetMapping(BASE+"/shipping-quote-receipts/{key}") public Map<String,Object> quoteReceipt(@PathVariable String organizationId,@PathVariable String key,HttpServletRequest r){query(r,Set.of());return execute(organizationId,a->Map.of("targetId",quotes.receipt(a,uuid(key)),"outcome","COMMITTED"));}
    private Map<String,Object> view(Scope a,BusinessShipments.Shipment s){var f=finance.get(a,s.facilityId(),s.id());if(!f.state().equals("UNPAID")||!f.currency().equals("VND")||f.amountVnd()!=s.totalVnd()||!f.quoteId().equals(s.quote().id()))throw new IllegalStateException("BUSINESS_OBLIGATION_BINDING_REQUIRED");return Map.of("simulation",true,"shipment",s,"obligation",f);}
    @PostMapping(BASE+"/shipment-preparations/{id}/bookings") public ResponseEntity<Map<String,Object>> book(@PathVariable String organizationId,@PathVariable String id,HttpServletRequest r)throws IOException{query(r,Set.of());UUID key=key(r),target=uuid(id);long expected=version(r);var v=body(r,Set.of("quoteId"));if(!v.get("quoteId").isString())throw problem(400,"VALIDATION_FAILED");UUID quote=uuid(v.get("quoteId").asString());var result=execute(organizationId,a->{var previous=shipments.replay(a.preparation(),target,expected,quote,key);if(previous.isPresent())return view(a,previous.get());var d=shipments.requireBookable(a.preparation(),target,expected);var q=quotes.get(a,quote);if(!route(a,q.route().originCode(),q.route().destinationCode()).equals(q.route()))throw new PilotQuoteFailure(PilotQuoteFailure.Code.UNSUPPORTED_ROUTE);UUID shipment=UUID.randomUUID();var consumed=quotes.consume(a,quote,target,expected,shipment);var s=shipments.confirm(a.preparation(),d,consumed,key,shipment);finance.recordUnpaid(a,d.facilityId(),shipment,quote,s.totalVnd());return view(a,s);});var s=(BusinessShipments.Shipment)result.get("shipment");return ResponseEntity.created(URI.create("/api/v1/merchant-organizations/"+organizationId+"/shipments/"+s.id())).cacheControl(CacheControl.noStore()).eTag("\"v1\"").body(result);}
    @GetMapping(BASE+"/shipments/{id}") public ResponseEntity<Map<String,Object>> get(@PathVariable String organizationId,@PathVariable String id,HttpServletRequest r){query(r,Set.of());return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag("\"v1\"").body(execute(organizationId,a->view(a,shipments.get(a.preparation(),uuid(id)))));}
    @GetMapping(BASE+"/shipments") public Map<String,Object> list(@PathVariable String organizationId,HttpServletRequest r){query(r,Set.of("page","size","search","status"));int page=number(r.getParameter("page"),0);if(number(r.getParameter("size"),20)!=20)throw problem(400,"VALIDATION_FAILED");return execute(organizationId,a->{var result=shipments.list(a.preparation(),page,r.getParameter("search"),r.getParameter("status"));return Map.of("items",result.items().stream().map(s->view(a,s)).toList(),"page",page,"size",20,"hasNext",result.hasNext());});}
    @GetMapping(BASE+"/shipping-booking-receipts/{key}") public Map<String,Object> receipt(@PathVariable String organizationId,@PathVariable String key,HttpServletRequest r){query(r,Set.of());return execute(organizationId,a->Map.of("targetId",shipments.receipt(a.preparation(),uuid(key)),"outcome","COMMITTED"));}
    @GetMapping(BASE+"/shipments/{id}/labels") public ResponseEntity<byte[]> labels(@PathVariable String organizationId,@PathVariable String id,HttpServletRequest r){query(r,Set.of());UUID target=uuid(id);return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).cacheControl(CacheControl.noStore()).header("Content-Disposition","attachment; filename=\"argopost-"+target+".pdf\"").header("X-Content-Type-Options","nosniff").body(execute(organizationId,a->shipments.labels(a.preparation(),target)));}
    private static JsonNode body(HttpServletRequest r,Set<String> fields)throws IOException{if(r.getContentType()==null||!r.getContentType().split(";",2)[0].equalsIgnoreCase("application/json"))throw problem(400,"VALIDATION_FAILED");byte[] bytes=r.getInputStream().readNBytes(4097);try{if(bytes.length>4096)throw problem(400,"VALIDATION_FAILED");var v=JSON.readTree(bytes);shape(v,fields,fields);return v;}catch(CustomerProfileHttp.HttpProblem rejected){throw rejected;}catch(Exception invalid){throw problem(400,"VALIDATION_FAILED");}finally{Arrays.fill(bytes,(byte)0);}}
}
